const beforeGuidesRender=render,previousOwnerAlerts=ownerAlerts,previousAlertCard=alertCard;
const guideFolders=[{id:'recepcion',title:'Recibir prendas',sub:'Registrar lo que pidió el cliente.',icon:'location',color:'lilac'},{id:'costura',title:'Costura y acabados',sub:'Así debe quedar cada arreglo.',icon:'shirt',color:'rose'},{id:'calidad',title:'Revisar la calidad',sub:'Qué comprobar antes de entregar.',icon:'check',color:'blue'},{id:'entregas',title:'Empaque y entregas',sub:'Cuidar e identificar las prendas.',icon:'box',color:'sand'}];
const guideTasks=['Todos los trabajos','Recepción de prendas','Hacer basta','Cambiar cierre','Ajustar talla','Control de calidad','Empaque y entregas'];
let guideFolder='all',guideSearch='',selectedGuide=null,guideObjectURL=null;
function initGuides(){state.workGuides??=[];state.guideReviews??={};state.guideQuestions??=[];RapicosturaTutorials.sync(state.workGuides)}
initGuides();
function guideById(id){return state.workGuides.find(g=>g.id===id)}
function openGuides(folder='all'){selectedGuide=null;guideFolder=folder;guideSearch='';selectedRepair=null;page='guides';render();scrollAppTop()}
function openGuide(id){const g=guideById(id);if(!g||g.hidden&&currentPerson!=='Dueña')return;selectedGuide=id;selectedRepair=null;page='guides';render();scrollAppTop()}
function visibleGuides(){return state.workGuides.filter(g=>!g.hidden||currentPerson==='Dueña')}
function guideCountLabel(n){return n+' '+(n===1?'video':'videos')+' para el equipo'}
function guideCard(g){const f=guideFolders.find(f=>f.id===g.folder),review=state.guideReviews[currentPerson+':'+g.id];return `<button class="guide-video-card" onclick="openGuide('${g.id}')"><span class="guide-video-icon ${f.color}">${icon('play')}</span><span><strong>${esc(g.title)}</strong><small>${esc(f.title)} · Versión ${g.version}</small><em>${g.hidden?'Oculta para el equipo':review?.version===g.version?'Ya la revisaste':'Video de la dueña'}</em></span><b>›</b></button>`}
function guideLibrary(){const owner=currentPerson==='Dueña',folder=guideFolders.find(f=>f.id===guideFolder),list=visibleGuides().filter(g=>(guideFolder==='all'||g.folder===guideFolder)&&`${g.title} ${g.goal} ${g.applies}`.toLowerCase().includes(guideSearch.toLowerCase()));return `${folder?'<button class="back-link" onclick="openGuides()">← Todas las carpetas</button>':''}<div class="greeting"><p class="eyebrow">ASÍ LO HACEMOS EN RAPICOSTURA</p><h1>${folder?folder.title:'Videos del taller'}</h1><p class="sub">${owner?'Comparte tu manera de trabajar con todo el equipo.':'Mira cómo quiere la dueña que hagamos cada proceso.'}</p></div>${!folder?`<section class="guides-hero"><span>${icon('play')}</span><div><h2>Una misma forma de trabajar.</h2><p>Videos claros, paso a paso, para cuidar cada prenda.</p>${owner?'<button onclick="guideEditor()">'+icon('plus')+' Subir un video</button>':''}</div></section><div class="guide-folders">${guideFolders.map(f=>`<button class="guide-folder ${f.color}" onclick="openGuides('${f.id}')"><span>${icon(f.icon)}</span><div><strong>${f.title}</strong><p>${f.sub}</p><small>${guideCountLabel(state.workGuides.filter(g=>g.folder===f.id&&!g.hidden).length)}</small></div><b>›</b></button>`).join('')}</div>`:owner?button('Subir video a esta carpeta','guideEditor()',true,'plus'):''}<div class="section-label"><h2>${folder?'Videos de esta carpeta':'Todos los videos'}</h2><span>${list.length}</span></div><input id="guide-search" class="owner-search" aria-label="Buscar un video" placeholder="Buscar un video…" value="${esc(guideSearch)}"><div id="guide-results" class="guide-results">${list.map(guideCard).join('')||guideEmpty(owner)}</div><p class="local-note">Los tutoriales publicados con la app están disponibles para todo el equipo. Las confirmaciones y los videos que subas desde este dispositivo se guardan aquí.</p>`}
function guideEmpty(owner){return `<div class="guides-empty">${icon('play')}<h3>${guideSearch?'No encontramos una guía':owner?'Todavía no hay videos':'No hay videos disponibles todavía'}</h3><p>${guideSearch?'Prueba con otro nombre o proceso.':owner?'Graba cómo haces el proceso y súbelo con una indicación clara.':'Cuando la dueña publique un video, podrás verla aquí.'}</p></div>`}
paths.play='<rect x="3" y="4" width="18" height="16" rx="4"/><path d="m10 8 6 4-6 4V8Z"/>';
function guideTaskOptions(){return [...new Set([...guideTasks,...state.repairs.map(r=>r.task)])]}
function guideEditor(id){if(currentPerson!=='Dueña')return;const old=id?guideById(id):null;modal(old?'Actualizar guía':'Subir video del taller',`<form id="guide-form"><label class="field">Nombre de la guía<input id="guide-title" maxlength="90" value="${esc(old?.title||'')}" placeholder="Ej. Cómo debe quedar una basta" required></label><label class="field">Carpeta<select id="guide-folder">${guideFolders.map(f=>`<option value="${f.id}" ${(old?.folder||guideFolder)===f.id?'selected':''}>${f.title}</option>`).join('')}</select></label><label class="field">Se aplica a<select id="guide-applies">${staffPick(guideTaskOptions(),old?.applies||'Todos los trabajos')}</select></label><label class="field">${old?'Reemplazar video (opcional)':'Video del proceso'}<input id="guide-upload" type="file" accept="video/*" ${old?'':'required'}></label><label class="field">¿Cómo debe quedar el trabajo?<textarea id="guide-goal" maxlength="700" placeholder="Ej. La costura debe quedar pareja y ambas piernas del mismo largo." required>${esc(old?.goal||'')}</textarea></label><details class="guide-extra"><summary>Añadir pasos y errores a evitar (opcional)</summary><label class="field">Pasos importantes, uno por línea<textarea id="guide-steps" maxlength="1600" placeholder="1. Confirmar la medida\n2. Marcar ambas piernas\n3. Revisar el acabado">${esc(old?.steps||'')}</textarea></label><label class="field">Errores que deben evitarse<textarea id="guide-mistakes" maxlength="700" placeholder="Ej. No cortar antes de comprobar la medida.">${esc(old?.mistakes||'')}</textarea></label></details><p class="local-note">Video de hasta 100 MB. Para reproducirlo en más equipos, usa MP4 o WebM compatible. Este prototipo lo guarda en el navegador.</p><div class="modalactions"><button class="btn" type="button" onclick="dialog.close()">Volver</button><button class="btn primary" id="guide-publish">${old?'Publicar nueva versión':'Publicar guía'}</button></div></form>`);document.getElementById('guide-form').onsubmit=async e=>{e.preventDefault();const file=document.getElementById('guide-upload').files[0];if(file&&(!file.type.startsWith('video/')||file.size>100*1024*1024)){toast('Elige un video de hasta 100 MB.');return}if(!old&&!file)return;const title=document.getElementById('guide-title').value.trim(),goal=document.getElementById('guide-goal').value.trim();if(!title||!goal)return;const g={...old,id:old?.id||'GUI-'+Date.now().toString(36).toUpperCase(),title,folder:document.getElementById('guide-folder').value,applies:document.getElementById('guide-applies').value,goal,steps:document.getElementById('guide-steps').value.trim(),mistakes:document.getElementById('guide-mistakes').value.trim(),version:(old?.version||0)+1,hidden:old?.hidden||false,updatedAt:Date.now(),mediaKey:old?.mediaKey,mediaName:old?.mediaName};const submit=document.getElementById('guide-publish');submit.disabled=true;submit.textContent='Guardando video…';try{if(file){delete g.publicUrl;g.mediaKey=g.id+'-v'+g.version;g.mediaName=file.name;await mediaPut(g.mediaKey,file)}if(old)state.workGuides[state.workGuides.findIndex(x=>x.id===old.id)]=g;else state.workGuides.push(g);dialog.close();selectedGuide=g.id;page='guides';save('La dueña publicó '+g.title+' · Versión '+g.version+'.');toast('Guía publicada para el equipo en este navegador.')}catch{submit.disabled=false;submit.textContent=old?'Publicar nueva versión':'Publicar guía';toast('No se pudo guardar el video. Prueba con uno más pequeño.')}}}
function guideDetail(){const g=guideById(selectedGuide);if(!g||g.hidden&&currentPerson!=='Dueña')return guideEmpty(currentPerson==='Dueña');const f=guideFolders.find(f=>f.id===g.folder),owner=currentPerson==='Dueña',review=state.guideReviews[currentPerson+':'+g.id],questions=state.guideQuestions.filter(q=>q.guideId===g.id&&(owner||q.who===currentPerson));return `<button class="back-link" onclick="openGuides('${g.folder}')">← ${f.title}</button><div class="greeting"><p class="eyebrow">VIDEO DE LA DUEÑA · VERSIÓN ${g.version}${g.hidden?' · OCULTO':''}</p><h1>${esc(g.title)}</h1><p class="sub">${esc(g.applies)}</p></div><section class="guide-player-panel"><div id="guide-player" class="guide-player"><span>Cargando el video guardado…</span></div><div class="guide-standard"><span>${icon('check')} ASÍ DEBE QUEDAR</span><p>${esc(g.goal)}</p></div>${g.steps?`<h2>Pasos importantes</h2><ol class="guide-steps">${g.steps.split('\n').filter(s=>s.trim()).map(s=>`<li>${esc(s.replace(/^\d+[.)]\s*/,''))}</li>`).join('')}</ol>`:''}${g.mistakes?`<div class="guide-mistakes"><strong>${icon('alert')} Evita estos errores</strong><p>${esc(g.mistakes)}</p></div>`:''}${owner?`<div class="worker-actions">${button('Editar guía',`guideEditor('${g.id}')`,true,'orders')}${button(g.hidden?'Volver a mostrar al equipo':'Ocultar al equipo',`guideVisibility('${g.id}')`,false)}</div><p class="local-note">Revisiones declaradas de esta versión: ${Object.values(state.guideReviews).filter(r=>r.guideId===g.id&&r.version===g.version).length}. Son declaraciones de las trabajadoras; no evalúan la calidad del trabajo.</p>`:`<div class="worker-actions">${button(review?.version===g.version?'Ya la revisaste':'Ya revisé esta guía',`markGuideReviewed('${g.id}')`,true,'check')}${button('Tengo una duda',`askGuide('${g.id}')`,false,'help')}</div><p class="local-note">Marca la revisión solo después de consultarla. No necesitas confirmar nada para reproducir el video.</p>`}</section>${questions.length?`<section class="guide-questions"><h2>${owner?'Dudas del equipo':'Mis dudas sobre esta guía'}</h2>${questions.map(q=>`<article><strong>${esc(q.who)} · Versión ${q.version}</strong><p>${esc(q.text)}</p>${q.answer?`<div><strong>Respuesta de la dueña</strong><p>${esc(q.answer)}</p></div>`:owner?button('Responder duda',`answerGuide('${q.id}')`,false,'help'):'<small>La dueña todavía no ha respondido.</small>'}</article>`).join('')}</section>`:''}`}
async function loadGuideVideo(){const g=guideById(selectedGuide),target=document.getElementById('guide-player');if(!g||!target)return;try{let source=g.publicUrl;if(!source){const db=await mediaDB();let blob;try{blob=await new Promise((resolve,reject)=>{const request=db.transaction('files').objectStore('files').get(g.mediaKey);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}finally{db.close()}if(!target.isConnected)return;if(!blob){target.innerHTML='<p>El video no está guardado en este navegador. La dueña debe volver a subirlo aquí.</p>';return}guideObjectURL=URL.createObjectURL(blob);source=guideObjectURL}if(!target.isConnected)return;const video=document.createElement('video');video.src=source;video.controls=true;video.playsInline=true;video.preload='metadata';video.setAttribute('aria-label',g.title);video.onerror=()=>{if(target.isConnected)target.innerHTML=g.publicUrl?'<p>No pudimos cargar el video. Revisa tu conexión y vuelve a abrir esta guía.</p>':'<p>No se pudo reproducir este archivo. Prueba con un MP4 o WebM compatible.</p>'};target.replaceChildren(video)}catch{if(target.isConnected)target.innerHTML='<p>No se pudo cargar el video. Intenta abrir la guía otra vez.</p>'}}
function markGuideReviewed(id){const g=guideById(id);if(!g||g.hidden||currentPerson==='Dueña')return;if(state.guideReviews[currentPerson+':'+id]?.version===g.version){toast('Ya registraste la revisión de esta versión.');return}state.guideReviews[currentPerson+':'+id]={guideId:id,who:currentPerson,version:g.version,at:Date.now()};save(currentPerson+' confirmó que revisó la guía '+g.title+' · Versión '+g.version+'.');toast('Revisión guardada. Puedes volver a ver el video cuando quieras.')}
function guideVisibility(id){const g=guideById(id);if(currentPerson!=='Dueña'||!g)return;modal(g.hidden?'Mostrar esta guía':'Ocultar esta guía',`<p>${g.hidden?'Volverá a estar disponible para el equipo.':'Dejará de aparecer para las trabajadoras. La dueña podrá mostrarla nuevamente.'}</p><div class="modalactions">${button('Volver','dialog.close()')}${button('Confirmar',`confirmGuideVisibility('${id}')`,true)}</div>`)}
function confirmGuideVisibility(id){const g=guideById(id);if(currentPerson!=='Dueña'||!g)return;g.hidden=!g.hidden;dialog.close();save('La dueña '+(g.hidden?'ocultó':'volvió a mostrar')+' la guía '+g.title+'.')}
function askGuide(id){const g=guideById(id);if(!g||currentPerson==='Dueña')return;modal('Preguntar sobre esta guía',`<form id="guide-question-form"><p>${esc(g.title)}</p><label class="field">¿Qué necesitas aclarar?<textarea id="guide-question-text" maxlength="500" placeholder="Ej. Mi máquina es distinta. ¿Cómo puedo hacer este paso?" required></textarea></label><p class="local-note">Es una consulta dentro del prototipo. No se envía un WhatsApp.</p><div class="modalactions"><button class="btn" type="button" onclick="dialog.close()">Volver</button><button class="btn primary">Guardar mi duda</button></div></form>`);document.getElementById('guide-question-form').onsubmit=e=>{e.preventDefault();const text=document.getElementById('guide-question-text').value.trim();if(!text)return;state.guideQuestions.push({id:'DUD-'+Date.now().toString(36).toUpperCase(),guideId:id,version:g.version,who:currentPerson,text,answer:'',at:Date.now()});dialog.close();save(currentPerson+' dejó una duda sobre la guía '+g.title+'.');toast('Tu duda quedó registrada para la dueña.')}}
function answerGuide(id){const q=state.guideQuestions.find(q=>q.id===id);if(!q||currentPerson!=='Dueña')return;modal('Responder a '+esc(q.who),`<form id="guide-answer-form"><div class="notice">${esc(q.text)}</div><label class="field">Tu explicación<textarea id="guide-answer-text" maxlength="700" required></textarea></label><div class="modalactions"><button class="btn" type="button" onclick="dialog.close()">Volver</button><button class="btn primary">Guardar respuesta</button></div></form>`);document.getElementById('guide-answer-form').onsubmit=e=>{e.preventDefault();const text=document.getElementById('guide-answer-text').value.trim();if(!text)return;q.answer=text;q.answeredAt=Date.now();dialog.close();save('La dueña respondió una duda de '+q.who+' sobre un proceso del taller.');toast('Respuesta guardada.')}}
ownerAlerts=function(){initGuides();return [...previousOwnerAlerts(),...(ownerDemo?[]:state.guideQuestions.filter(q=>!q.answer).map(q=>({kind:'help',title:q.who+' tiene una duda',description:guideById(q.guideId)?.title||'Guía del taller',guide:q.guideId,label:'Ver duda',icon:'play'})))]};
alertCard=function(a){return a.guide?`<div class="owner-alert help"><span>${icon('help')}</span><div><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><button onclick="openGuide('${a.guide}')">Ver duda →</button></div></div>`:previousAlertCard(a)};
function relatedGuides(task){return state.workGuides.filter(g=>!g.hidden&&(g.applies==='Todos los trabajos'||g.applies===task))}
render=function(){initGuides();if(guideObjectURL){URL.revokeObjectURL(guideObjectURL);guideObjectURL=null}beforeGuidesRender();const inGuides=page==='guides';if(inGuides){main.innerHTML=(selectedGuide?guideDetail():guideLibrary())+personaControl();const search=document.getElementById('guide-search');if(search)search.oninput=e=>{guideSearch=e.target.value;const list=visibleGuides().filter(g=>(guideFolder==='all'||g.folder===guideFolder)&&`${g.title} ${g.goal} ${g.applies}`.toLowerCase().includes(guideSearch.toLowerCase()));document.getElementById('guide-results').innerHTML=list.map(guideCard).join('')||guideEmpty(currentPerson==='Dueña')};if(selectedGuide)loadGuideVideo()}else if(selectedRepair&&currentPerson!=='Dueña'){const r=selected(),related=r?relatedGuides(r.task):[];if(related.length){const panel=main.querySelector('.task-body')||main.querySelector('.panel');if(panel)panel.insertAdjacentHTML('beforeend',`<section class="related-guides"><h3>${icon('play')} Así lo quiere la dueña</h3>${related.slice(0,3).map(guideCard).join('')}</section>`)}}else if(page==='reception'&&currentPerson!=='Dueña'&&relatedGuides('Recepción de prendas').length){main.querySelector('.greeting')?.insertAdjacentHTML('afterend','<button class="guides-shortcut" onclick="openGuides(\'recepcion\')">'+icon('play')+' Ver cómo recibimos una prenda</button>')}const nav=document.getElementById('mobile-nav');const item=document.createElement('button');item.className=inGuides?'active':'';if(inGuides){for(const b of nav.querySelectorAll('button')){b.classList.remove('active');b.removeAttribute('aria-current')}item.setAttribute('aria-current','page')}item.innerHTML=icon('play')+'<span>Guías</span>';item.onclick=()=>openGuides();nav.insertBefore(item,nav.children[currentPerson==='Dueña'?2:1]||null);nav.classList.add('with-guides')};
window.addEventListener('storage',event=>{if(event.key==='hilando-v1'&&currentPerson!=='Dueña'&&page==='guides'){initGuides();render()}});
if(new URLSearchParams(location.search).get('seccion')==='guias')page='guides';
render();

